import React from 'react';
import './App.css'; // Assure-toi que ce fichier est importé
import Menu from './components/menu.jsx';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import AccueilPage from './pages/accueilpage.jsx'; // Assure-toi d'avoir ce fichier
import ChambrePage from './pages/chambrepage.jsx'; // Ajustement du nom
import EtablissementPage from './pages/etablissementpage.jsx'; // Ajustement du nom
import EtudiantPage from './pages/etudiantpage.jsx'; // Ajustement du nom
import LoginPage from './pages/loginpage.jsx'; // Ajustement du nom
import ReservationPage from './pages/reservationpage.jsx'; // Ajustement du nom


function App() {
  return (
    <Router>
      <div>
        <menu />
        <div className="pt-16"> {/* Ajoute du padding pour éviter le chevauchement avec le menu sticky */}
          <Routes>
            <Route path="/" element={<AccueilPage />} /> {/* Route pour la page d'accueil */}
            <Route path="/chambres" element={<ChambrePage />} /> {/* Route pour la page des chambres */}
            <Route path="/etablissements" element={<EtablissementPage />} /> {/* Route pour la page des établissements */}
            <Route path="/etudiants" element={<EtudiantPage />} /> {/* Route pour la page des étudiants */}
            <Route path="/login" element={<LoginPage />} /> {/* Route pour la page de connexion */}
            <Route path="/reservations" element={<ReservationPage />} /> {/* Route pour la page des réservations */}
            {/* Tu peux ajouter d'autres routes ici */}
          </Routes>
        </div>
      </div>
    </Router>
  );
}

export default App;
